-- The map from the garment registry's option keys to the base article catalogue's option codes
-- (plans/platform-v5.md section 6 item 3, decision 0099).
--
-- The design object holds the registry's own words (`neckline: "crew"`, `cuffs: "rib-cuff"`); the catalogue holds
-- the codes a factory approved (`C01`, `K01`, `P00`). One row joins one registry choice to one catalogue code, and
-- only where a published file says the two are the same thing: `sources` quotes that file word for word, and
-- lib/option-codes/seed/rows.test.ts reads every cited file and fails if a quote is not in it.
--
-- A row that carries no code is not a hole in the table: `kind` says whether the catalogue carries the question
-- somewhere other than an option code (`not_an_option`, with the source that says so) or whether nothing published
-- joins them at all (`no_code_yet`, which the tech pack states in words and the rulebook counts as R-GAP-000).
--
-- Platform data, like the catalogue itself: signed-in members read it; only the server's own key writes it. The
-- foreign key to `option_defs` means a mapped row can only ever name a code the catalogue really approved for that
-- article and that group, so an invented code cannot be stored at all.
--
-- The seed at the end is generated by lib/option-codes/seed/sql.ts from lib/option-codes/seed/rows.ts;
-- lib/option-codes/seed/sql.test.ts fails if the two drift apart.

create table public.option_code_map (
  id uuid primary key default gen_random_uuid(),
  article_id uuid not null references public.base_articles (id) on delete cascade,
  position integer not null check (position >= 0),
  -- The garment registry's own option key (lib/garment/registry), or null for a catalogue group no key feeds.
  registry_key text check (registry_key is null or registry_key ~ '^[a-z][a-z0-9-]{0,63}$'),
  -- The registry choice the row is about, or null when the row holds for every choice of the key.
  registry_choice text check (registry_choice is null or registry_choice ~ '^[a-z][a-z0-9-]{0,63}$'),
  -- The catalogue option group (option_defs.option_group), or null where the catalogue has no group for the key.
  option_group text check (option_group is null or option_group ~ '^[a-z][a-z0-9_]{0,63}$'),
  option_code text check (option_code is null or option_code ~ '^[A-Z][0-9]{2}$'),
  kind text not null check (kind in ('mapped', 'not_an_option', 'no_code_yet')),
  -- The published sources, quoted: [{"file": "docs/spec/...", "quote": "..."}]. Empty only for a gap.
  sources jsonb not null default '[]'::jsonb check (jsonb_typeof(sources) = 'array'),
  -- Where the catalogue carries it instead, or what is missing. Null only for a mapped row.
  note text check (note is null or length(btrim(note)) between 1 and 1000),
  -- Every row explains itself (plan v5, spec decision 11). R-GAP-000 while no rule is written, never nothing.
  rule_id text not null check (rule_id ~ '^R-[A-Z]{2,5}-\d{3}$'),
  created_at timestamptz not null default now(),
  unique (article_id, position),
  -- One row per question: per choice of a registry key, or one row for the whole key, or one for a group.
  unique (article_id, registry_key, registry_choice, option_group),
  -- A mapped row names a code the catalogue approved for that article and group; the others name no code at all.
  constraint option_code_map_mapped_is_complete check (
    case kind
      when 'mapped' then option_code is not null and option_group is not null and registry_key is not null
        and registry_choice is not null and jsonb_array_length(sources) > 0 and note is null
      when 'not_an_option' then option_code is null and registry_key is not null and jsonb_array_length(sources) > 0
        and note is not null
      else option_code is null and jsonb_array_length(sources) = 0 and note is not null
    end
  ),
  constraint option_code_map_code_is_approved
    foreign key (article_id, option_group, option_code) references public.option_defs (article_id, option_group, code)
);

comment on table public.option_code_map is
  'Joins the garment registry''s option keys to the catalogue''s option codes. A mapped row quotes the published source that says the two are the same thing; a row with no code says so and why.';
comment on column public.option_code_map.sources is
  'The published files the row quotes, word for word, so the mapping can be checked against them. Empty only where nothing published joins the two.';
comment on column public.option_code_map.kind is
  'mapped: the registry choice is this catalogue code. not_an_option: the catalogue carries the question elsewhere. no_code_yet: nothing published joins them.';

create index option_code_map_registry_key_idx on public.option_code_map (registry_key);

-- Rights: signed-in members read; the server's key writes. Same idiom as option_defs (20261101010000).
revoke all on public.option_code_map from public, anon, authenticated, service_role;
grant select on public.option_code_map to authenticated, service_role;
grant insert, update, delete on public.option_code_map to service_role;

alter table public.option_code_map enable row level security;

create policy "members read option_code_map"
  on public.option_code_map for select to authenticated
  using (exists (select 1 from public.memberships m where m.user_id = (select auth.uid())));

-- There are no insert, update or delete policies, on purpose.

